import sys, pandas as pd, numpy as np; sys.path.insert(0, sys.argv[1]+"/analysis"); from load_helper import load
pd.set_option("display.width",250); pd.set_option("display.max_columns",40); pd.set_option("display.max_colwidth",80); pd.set_option("display.max_rows",100)
d=load(sys.argv[1]+"/data/case_workbook.xlsx"); P=print
ro,mp,opp,app,bill=d["roster"],d["map"],d["opp"],d["app"],d["bill"]
P("### MAPPING", mp.shape, "| unique crm", mp.crm_account_id.nunique(), "app", mp.app_account_id.nunique(), "billing", mp.billing_account_id.nunique(), "| nulls", mp.isna().sum().to_dict())
P("dup crm ids:", mp[mp.crm_account_id.duplicated(keep=False)].shape[0], "| dup app:", mp[mp.app_account_id.duplicated(keep=False)].shape[0], "| dup billing:", mp[mp.billing_account_id.duplicated(keep=False)].shape[0])
P("\n### OPP EXPORT", opp.shape, "| opp ids unique", opp.opportunity_id.nunique(), "| accounts", opp.crm_account_id.nunique())
P("stage:", opp.opportunity_stage.value_counts(dropna=False).to_dict()); P("account_type:", opp.account_type.value_counts(dropna=False).to_dict()); P("segment:", opp.segment.value_counts(dropna=False).to_dict()); P("net_terms:", opp.net_terms.value_counts(dropna=False).to_dict())
P("closed_by null:", opp.closed_by_owner_id.isna().sum(), "| crm_owner null:", opp.crm_owner_id.isna().sum(), "| closed_won_date null:", opp.closed_won_date.isna().sum(), "| eff start null:", opp.effective_start_date.isna().sum())
P("closed_won_date populated on non-Closed Won rows:", ((opp.opportunity_stage!="Closed Won")&opp.closed_won_date.notna()).sum(), "| Closed Won rows missing closed_won_date:", ((opp.opportunity_stage=="Closed Won")&opp.closed_won_date.isna()).sum())
P("closed_by ids not on roster:", (~opp.closed_by_owner_id.dropna().isin(ro.crm_owner_id)).sum(), "distinct:", opp.loc[~opp.closed_by_owner_id.isin(ro.crm_owner_id)&opp.closed_by_owner_id.notna(),"closed_by_owner_id"].nunique())
P("crm_owner ids not on roster:", (~opp.crm_owner_id.dropna().isin(ro.crm_owner_id)).sum(), "distinct:", opp.loc[~opp.crm_owner_id.isin(ro.crm_owner_id)&opp.crm_owner_id.notna(),"crm_owner_id"].nunique())
P("accounts not in mapping:", (~opp.crm_account_id.isin(mp.crm_account_id)).sum(), "| mapping crm ids not in opp:", (~mp.crm_account_id.isin(opp.crm_account_id)).sum())
g=opp.groupby("crm_account_id"); P("opps per account:", g.size().value_counts().sort_index().to_dict())
for c in ["charge_rate_per_shift","pay_rate_per_shift","net_terms","segment","account_type","crm_owner_id"]:
    n=(g[c].nunique(dropna=False)>1).sum(); P(f"accounts with >1 distinct {c}: {n}")
cw=opp[opp.opportunity_stage=="Closed Won"]; P("accounts with >=1 Closed Won:", cw.crm_account_id.nunique(), "| accounts with 0 Closed Won:", opp.crm_account_id.nunique()-cw.crm_account_id.nunique())
gc=cw.groupby("crm_account_id"); P("accounts with >1 Closed Won:", (gc.size()>1).sum(), "| of which closed_by differs across wins:", (gc.closed_by_owner_id.nunique(dropna=False)>1).sum())
P("effective_start_date range:", opp.effective_start_date.min(), "->", opp.effective_start_date.max(), "| closed_won_date range:", opp.closed_won_date.min(), "->", opp.closed_won_date.max())
P("eff start before closed won date:", (opp.effective_start_date<opp.closed_won_date).sum(), "| eff start > 90 days after closed won:", ((opp.effective_start_date-opp.closed_won_date).dt.days>90).sum())
P("margin per shift (charge-pay) describe:\n", (opp.charge_rate_per_shift-opp.pay_rate_per_shift).describe().round(1).to_string()); P("non-positive margin rows:", ((opp.charge_rate_per_shift-opp.pay_rate_per_shift)<=0).sum())
P("rates by segment:\n", opp.groupby("segment")[["charge_rate_per_shift","pay_rate_per_shift"]].describe().round(0).to_string())
P("dup opportunity rows (all cols):", opp.duplicated().sum(), "| dup opp ids:", opp.opportunity_id.duplicated().sum())
P("\n### APP EXPORT", app.shape, "| shift ids unique", app.shift_id.nunique(), "| accounts", app.app_account_id.nunique())
P("worked flag:", app.worked_shift.value_counts(dropna=False).to_dict(), "| dtype", app.worked_shift.dtype)
P("posted range:", app.shift_posted_date.min(), "->", app.shift_posted_date.max(), "| worked range:", app.shift_worked_date.min(), "->", app.shift_worked_date.max())
P("worked TRUE with null worked date:", (app.worked_shift.astype(str).str.upper().eq("TRUE")&app.shift_worked_date.isna()).sum(), "| worked FALSE with a worked date:", (app.worked_shift.astype(str).str.upper().eq("FALSE")&app.shift_worked_date.notna()).sum())
P("worked date before posted date:", (app.shift_worked_date<app.shift_posted_date).sum(), "| lag days describe:\n", (app.shift_worked_date-app.shift_posted_date).dt.days.describe().round(1).to_string())
P("worked shifts by month:", app[app.shift_worked_date.notna()].groupby(app.shift_worked_date.dt.to_period("M")).size().to_dict())
P("posted shifts by month:", app.groupby(app.shift_posted_date.dt.to_period("M")).size().to_dict())
fw=app.groupby("app_account_id").account_first_worked_shift_date.nunique(dropna=False); P("accounts with >1 distinct first-worked date:", (fw>1).sum(), "| null first worked:", app.account_first_worked_shift_date.isna().sum())
mn=app[app.shift_worked_date.notna()].groupby("app_account_id").shift_worked_date.min(); fwd=app.groupby("app_account_id").account_first_worked_shift_date.first()
cmp=pd.concat([mn.rename("min_worked_in_extract"),fwd.rename("first_worked_given")],axis=1); P("accounts where min worked date in extract < given first worked date:", (cmp.min_worked_in_extract<cmp.first_worked_given).sum(), "| accounts with first worked inside extract window (>=2026-03-01):", (cmp.first_worked_given>="2026-03-01").sum(), "| of those, min worked == given:", ((cmp.first_worked_given>="2026-03-01")&(cmp.min_worked_in_extract==cmp.first_worked_given)).sum())
P("first worked date > min worked date (given later than observed):", (cmp.first_worked_given>cmp.min_worked_in_extract).sum())
P("app accounts not in mapping:", (~app.app_account_id.isin(mp.app_account_id)).sum(), "rows;", app.loc[~app.app_account_id.isin(mp.app_account_id),"app_account_id"].nunique(), "accounts")
P("dup shift ids:", app.shift_id.duplicated().sum(), "| fully duplicated rows:", app.duplicated().sum())
dups=app[app.shift_id.duplicated(keep=False)].sort_values("shift_id"); P(dups.head(10).to_string(index=False))
P("shifts per account describe:\n", app.groupby("app_account_id").size().describe().round(0).to_string())
P("\n### BILLING", bill.shape, "| status:", bill.ticket_status.value_counts(dropna=False).to_dict(), "| months:", bill.billing_month.value_counts(dropna=False).to_dict(), "| types:", bill.ticket_type.value_counts(dropna=False).to_dict())
P("credit_amount describe:\n", bill.credit_amount.describe().round(1).to_string(), "\nnegative/zero amounts:", (bill.credit_amount<=0).sum())
P("billing ids not in mapping:", (~bill.billing_account_id.isin(mp.billing_account_id)).sum(), "| shift ids not in app export:", (~bill.shift_id.isin(app.shift_id)).sum(), "| null shift id:", bill.shift_id.isna().sum())
bj=bill.merge(app[["shift_id","app_account_id","shift_worked_date","worked_shift"]],on="shift_id",how="left").merge(mp,on="app_account_id",how="left")
P("tickets whose shift's account != billing account:", (bj.billing_account_id_x!=bj.billing_account_id_y).sum() if "billing_account_id_x" in bj else "n/a")
bj["worked_month"]=bj.shift_worked_date.dt.strftime("%Y-%m"); P("tickets where billing_month != shift worked month:", (bj.worked_month!=bj.billing_month).sum(), "| tickets on unworked shifts:", (bj.worked_shift.astype(str).str.upper()=="FALSE").sum())
P("dup tickets (same shift id):", bill.shift_id.duplicated().sum(), "| fully duplicated rows:", bill.duplicated().sum())
P("credit amount vs account margin: tickets > charge rate:", 0)
P("approved credits by month: ", bill[bill.ticket_status=="approved"].groupby("billing_month").credit_amount.agg(["count","sum"]).to_dict())
